<?php declare(strict_types=1);require __DIR__.'/bootstrap.php';$login=valid_login((string)($_GET['login']??''));?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tráfego Huawei</title>
<style>:root{font-family:Arial;color:#183246;background:#eaf1f5}body{margin:0;padding:28px}.layout{max-width:1420px;margin:auto;display:grid;grid-template-columns:360px 1fr;gap:28px}.card{background:#fff;border-radius:16px;padding:26px;box-shadow:0 8px 26px #17344c15}.profile{background:#193649;color:#fff}.kv{display:grid;grid-template-columns:125px 1fr;border-bottom:1px solid #ffffff20;padding:10px 0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.btn{padding:10px 14px;border-radius:8px;text-decoration:none;border:0;background:#1371c8;color:#fff}.danger{background:#bd2732}.muted{color:#657482}.chart{width:100%;height:320px;background:#f5f8fa;border:1px solid #dbe5eb;border-radius:12px}.legend{font-size:18px;margin-top:14px;display:flex;gap:28px}.search{width:100%;box-sizing:border-box;padding:13px;border:1px solid #bdcbd5;border-radius:8px}@media(max-width:900px){.layout{grid-template-columns:1fr}}</style></head><body><div class="layout">
<aside class="card profile"><small>MONITORAMENTO DO CLIENTE</small><h1 id="clientName"><?=htmlspecialchars($login)?></h1><div id="fields"></div><div class="actions"><a id="view" class="btn" target="_blank">Cadastro</a><a id="edit" class="btn" target="_blank">Alterar</a><a class="btn" target="_blank" href="/admin/addons/busca_inteligente/det_conn.php?login=<?=urlencode($login)?>">Histórico</a></div></aside>
<main class="card"><input class="search" placeholder="Buscar outro cliente online por login" onkeydown="if(event.key==='Enter')location='detail.php?login='+encodeURIComponent(this.value)"><div style="display:flex;justify-content:space-between"><h2>Tráfego em tempo real</h2><a class="btn danger" href="./">Sair</a></div><canvas id="chart" class="chart" width="1000" height="320"></canvas><div class="legend"><span>↓ Download <b id="down">0.00</b> Mbps</span><span>↑ Upload <b id="up">0.00</b> Mbps</span></div><p id="status" class="muted">Iniciando consulta sob demanda…</p></main></div>
<script>const login=<?=json_encode($login)?>,ctx=chart.getContext('2d');let prev=null,points=[];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('api_client.php?login='+encodeURIComponent(login)).then(r=>r.json()).then(j=>{let c=j.client;clientName.textContent=c.nome||c.username;fields.innerHTML=[['Login',c.username],['Status','Online'],['Contrato',c.contrato||'-'],['Conectado',c.acctstarttime],['IP',c.framedipaddress],['MAC',c.callingstationid],['Porta',c.nasportid],['Plano',c.plano||'-'],['Ramal',c.ramal||'-']].map(x=>`<div class="kv"><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div>`).join('');if(c.uuid_cliente){view.href='/admin/cliente_det.hhvm?uuid='+encodeURIComponent(c.uuid_cliente);edit.href='/admin/cliente_alt.hhvm?uuid='+encodeURIComponent(c.uuid_cliente)}});function draw(){ctx.clearRect(0,0,1000,320);let max=Math.max(1,...points.flatMap(p=>[p.d,p.u]));for(const[k,color]of[['d','#e75252'],['u','#2679c9']]){ctx.strokeStyle=color;ctx.lineWidth=4;ctx.beginPath();points.forEach((p,i)=>{let x=25+i*950/Math.max(1,points.length-1),y=295-p[k]/max*270;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}}async function sample(){try{let j=await fetch('api_realtime.php?login='+encodeURIComponent(login),{cache:'no-store'}).then(r=>r.json());if(!j.ok)throw Error(j.error);if(prev){let s=(j.sample_ms-prev.sample_ms)/1000,d=Math.max(0,(j.down_bytes-prev.down_bytes)*8/s/1e6),u=Math.max(0,(j.up_bytes-prev.up_bytes)*8/s/1e6);down.textContent=d.toFixed(2);up.textContent=u.toFixed(2);points.push({d,u});if(points.length>30)points.shift();draw()}prev=j;status.textContent=(j.interface||'Huawei')+' · '+(j.online_time||'')+' · amostra a cada 3 s'}catch(e){status.textContent=e.message}}sample();setInterval(sample,3000);</script></body></html>
